<template>
  <Teleport to="body"><div class="sales-entry" role="dialog" aria-modal="true" aria-label="新增业务下单">
    <header class="sales-entry-head"><b>新增业务下单</b><small :class="{danger:draftError}">{{draftError||draftMessage||`${countdown}s 后自动保存草稿`}}</small><button v-if="availableDraft" @click="restoreDraft()">继续历史草稿</button><button class="entry-x" aria-label="关闭下单" @click="close()">×</button></header>
    <div class="sales-entry-body" :aria-busy="loading">
      <p v-if="loading" class="entry-notice">正在读取下单资料…</p><p v-if="error" class="entry-error" role="alert">{{error}}</p>
      <section class="entry-section"><button class="section-title" @click="fold.basic=!fold.basic"><span class="step">1</span><b>基础信息</b><span class="chevron">{{fold.basic?'⌄':'⌃'}}</span></button><div v-show="!fold.basic" class="basic-fields">
        <label><span><i>*</i>客户</span><select v-model="form.customer_id" @change="customerChanged()"><option :value="null">选择客户</option><option v-for="c in customers" :value="c.id" :key="c.id">{{c.name}}</option></select></label>
        <label><span>业务员</span><select v-model="form.manager"><option :value="auth.user?.name||auth.user?.username">{{auth.user?.name||auth.user?.username}}</option><option v-for="u in salespeople.filter(u=>u.name!==auth.user?.name)" :key="u.id" :value="u.name">{{u.name}}</option></select></label><label><span>销售日期</span><input type="date" v-model="form.order_date"/></label>
        <label><span><i>*</i>销售单号</span><input v-model="form.order_no" maxlength="80" placeholder="填写销售单号"/></label><label><span><i>*</i>店铺名称</span><input v-model="form.shop_name" maxlength="255" placeholder="填写店铺名称"/></label><label><span><i>*</i>店铺订单编号</span><input v-model="form.shop_order_no" maxlength="255" placeholder="填写店铺订单编号"/></label>
        <label><span><i>*</i>交货天数</span><input type="number" v-model.number="form.delivery_days" min="1" max="3650" placeholder="请输入货期" list="delivery-options"/><datalist id="delivery-options"><option v-for="d in [7,10,15,20,30,45,60,90]" :key="d" :value="d"/></datalist></label><label><span>运费 USD</span><div class="stepper"><button @click="adjust('freight',-1)">−</button><input type="number" v-model.number="form.freight" min="0" step="0.01"/><button @click="adjust('freight',1)">＋</button></div></label><label><span><i>*</i>标签</span><input v-model="tagText" placeholder="标签，多个以逗号分隔" maxlength="1000"/></label>
        <label class="full-field"><span>备注</span><textarea rows="2" v-model="form.remark" placeholder="请输入" maxlength="2000"/></label>
        <details class="shipping-details"><summary>收货信息（选择客户后自动带出）</summary><div class="basic-fields"><label><span>收货人</span><input v-model="form.recipient_name" placeholder="选择客户后带出，可按本单调整"/></label><label><span>联系电话</span><input v-model="form.recipient_phone"/></label><label><span>目标交期</span><input type="date" v-model="form.delivery_date"/></label><label class="full-field"><span>收货地址</span><input v-model="form.shipping_address" maxlength="2000"/></label></div></details>
      </div></section>
      <section class="entry-section"><button class="section-title" @click="fold.products=!fold.products"><span class="step">2</span><b>商品信息</b><small>{{form.items.length}} 款商品</small><span class="chevron">{{fold.products?'⌄':'⌃'}}</span></button><div v-show="!fold.products" class="products-content">
        <div class="selected-products"><div><b>已选商品</b><small>{{form.items.length}} 款　总数量 {{totals.qty}}　总金额 USD {{totals.goods.toFixed(2)}}</small></div><button @click="toggleStock()">{{form.items.every(i=>!i.stock_open)?'展开':'收起'}}全部库存参考</button><button class="primary" @click="productOpen=true">选择商品</button><button class="primary" @click="syncMaterials()">一键同步商品辅料信息</button></div>
        <nav v-if="form.items.length" class="order-product-tabs" role="tablist" aria-label="已选商品款号"><button v-for="(item,index) in form.items" :key="item.key" type="button" role="tab" :id="'product-tab-'+item.key" :aria-selected="activeItemKey===item.key" :aria-controls="'product-panel-'+item.key" :tabindex="activeItemKey===item.key?0:-1" :class="{active:activeItemKey===item.key}" @click="activeItemKey=item.key" @keydown.right.prevent="moveTab(index,1)" @keydown.left.prevent="moveTab(index,-1)"><img v-if="item.effect_image_url" :src="item.effect_image_url" alt=""/><b>{{item.style_no||item.product_name||'商品 '+(index+1)}}</b><small>{{itemTotals(item).qty}} 件 · USD {{itemTotals(item).goods.toFixed(2)}}</small></button></nav>
        <section v-for="(item,index) in form.items" :key="item.key" v-show="activeItemKey===item.key" :id="'product-panel-'+item.key" class="order-product-panel" :class="{active:activeItemKey===item.key}" role="tabpanel" :aria-labelledby="'product-tab-'+item.key"><SalesOrderMatrix :item="item" :index="index" :stock="stock" :stock-error="stockError" :rate="rate" :templates="templates" @remove="removeItem(index)" @templates-changed="$emit('templates-changed')"/></section>
        <p v-if="!form.items.length" class="entry-notice">暂无商品，请点击“选择商品”添加已完成打版的样衣。</p>
      </div></section>
      <p v-if="form.source_pre_order_id && (form.pre_order_total_usd!=null||form.pre_order_payment_ratio!=null)" class="entry-notice">预下单约定总金额：{{form.pre_order_total_usd==null?'—':'USD '+Number(form.pre_order_total_usd).toFixed(2)}}；付款比例：{{form.pre_order_payment_ratio==null?'—':form.pre_order_payment_ratio+'%'}}。请核对本单商品金额和约定定金后保存。</p>
      <section class="entry-section"><button class="section-title" @click="fold.other=!fold.other"><span class="step">3</span><b>其他信息</b><small>{{form.attachments.length}}</small><span class="chevron">{{fold.other?'⌄':'⌃'}}</span></button><div v-show="!fold.other" class="other-fields">
        <div><label>发货方式</label><label class="radio"><input type="radio" v-model="form.delivery_method" value="自提"/> 自提</label><label class="radio"><input type="radio" v-model="form.delivery_method" value="快递"/> 快递</label></div>
        <div class="attachment-line"><label>附件上传</label><div class="attachment-drop" @dragover.prevent @drop.prevent="uploadFiles($event.dataTransfer.files)"><button :disabled="uploading" @click="fileInput.click()"><span>☁</span>{{uploading?'上传中…':'拖到 / 点击上传'}}</button><input ref="fileInput" type="file" multiple hidden @change="uploadFiles($event.target.files)"/></div><ul><li v-for="(a,i) in form.attachments" :key="a.url">{{a.filename}} <button class="link danger" @click="form.attachments.splice(i,1)">移除</button></li></ul></div>
        <div><label>优惠金额 USD</label><div class="stepper"><button @click="adjust('discount',-1)">−</button><input type="number" min="0" step="0.01" v-model.number="form.discount"/><button @click="adjust('discount',1)">＋</button></div></div><div><label>附加金额 USD</label><div class="stepper"><button @click="adjust('surcharge',-1)">−</button><input type="number" min="0" step="0.01" v-model.number="form.surcharge"/><button @click="adjust('surcharge',1)">＋</button></div></div>
        <div><label>合计总金额</label><strong class="orange">USD {{totals.total.toFixed(2)}}</strong><small>商品 {{totals.goods.toFixed(2)}} + 税 {{totals.tax.toFixed(2)}} + 运费 + 附加 − 优惠</small></div><div><label>付款方式</label><span>定金 USD</span><div class="stepper"><button @click="adjust('deposit',-1)">−</button><input type="number" min="0" step="0.01" v-model.number="form.deposit"/><button @click="adjust('deposit',1)">＋</button></div><span>尾款 <b class="blue">{{totals.balance.toFixed(2)}}</b></span><small>约定定金不代表已收款</small></div>
      </div></section>
    </div>
    <footer class="sales-entry-foot"><span>合计总金额 <strong class="orange">{{totals.total.toFixed(2)}}</strong></span><span>定金 <b>{{Number(form.deposit||0).toFixed(2)}}</b></span><span>尾款 <b class="blue">{{totals.balance.toFixed(2)}}</b></span><small>USD · 汇率 {{rate}}</small><div class="foot-actions"><button :disabled="saving||uploading" @click="close()">关闭</button><button class="primary" :disabled="saving||loading||uploading||!!draftError" @click="submit()">{{saving?'保存中…':'保存'}}</button></div></footer>
    <div v-if="productOpen" class="entry-dialog-mask"><section class="entry-dialog product-dialog" role="dialog" aria-modal="true" aria-label="选择已打版商品"><header class="product-picker-head"><div><h3>选择商品</h3><small>样衣管理 · 仅显示已完成打版的锁定版本</small></div><button title="关闭商品选择" @click="productOpen=false">×</button></header><div class="product-picker-search"><input v-model="productSearch" placeholder="搜索款号 / 商品名称"/><span>共 {{ filteredProducts.length }} 款</span></div><div class="product-options"><button v-for="p in filteredProducts" :key="p.id" :class="{'product-chosen':!!selectedProduct(p)}" @click="selectProduct(p)"><img v-if="p.image_url" :src="p.image_url" alt="点击放大商品图片" title="点击放大图片" @click.stop="openImage(p.image_url,p.style_no||p.name)"/><b>{{p.style_no||p.sku}}</b><span>{{p.name}}</span><small>{{selectedProduct(p)?'已选择 · 点击定位':'选择'}}</small></button><p v-if="!filteredProducts.length">暂无已完成打版的匹配样衣。未完成打版的款式请先走预下单、开发及打版流程。</p></div><footer><button @click="productOpen=false">关闭</button></footer></section></div>
  </div></Teleport>
</template>
<script setup>

import {reactive,ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {api} from '../api';
import {auth} from '../store/auth';
import {openImage} from '../store/viewer';
import {localDate} from '../utils/time';
import {entryId,entryRound as round} from '../utils/orderEntry';
import SalesOrderMatrix from './SalesOrderMatrix.vue';
const props=defineProps({initial:Object,customers:Array,products:Array,rate:Number,templates:Array});const emit=defineEmits(['close','saved','templates-changed']);
const DEFAULT_SIZES=['NB','0-3M','3-6M','6-12M','12-18M','18-24M','2T','3T','4T','5-6T','6-7T','7-8T','8-9T','9-10T','10-12T','12-14T','14-16T','16T'];
const DEFAULT_COLORS=['纯色1',...Array.from({length:9},(_,i)=>'印花'+String(i+1).padStart(3,'0'))];
function normalizeItem(it){let colors=(it.colors||[]).filter(c=>c.color);if(!colors.length)colors=DEFAULT_COLORS.map(color=>({color,sizes:DEFAULT_SIZES.map(size=>({size,qty:0,usd_price:0}))}));return {...JSON.parse(JSON.stringify(it)),key:it.key||entryId(),product_name:it.product_name||'',style_no:it.style_no||'',effect_image_url:it.effect_image_url||'',detail_images:it.detail_images||[],colors:colors.map(c=>({...c,sizes:c.sizes.map(s=>({...s,entry_price:s.entry_price??s.usd_price??null}))})),materials:it.materials||[],crafts:it.crafts||[],color_images:it.color_images||{},customer_sizes:it.customer_sizes||{},stock_open:true,unit_price:it.unit_price??0,tax_rate:it.tax_rate??0,currency:it.currency||'USD',split_price:it.split_price??false};}
const form=reactive({...JSON.parse(JSON.stringify(props.initial||{})),entry_version:1,request_no:entryId(),scope_key:props.initial?.source_pre_order_id?'pre:'+props.initial.source_pre_order_id:'new',manager:props.initial?.manager||auth.user?.name||auth.user?.username,order_date:props.initial?.source_pre_order_id?(props.initial.order_date||''):'',delivery_days:props.initial?.source_pre_order_id?(props.initial.delivery_days||''):'',delivery_method:props.initial?.source_pre_order_id?(props.initial.delivery_method||''):'',freight:Number(props.initial?.freight||0),discount:0,surcharge:0,deposit:props.initial?.source_pre_order_id?Number(props.initial.deposit||0):0,tags:[],attachments:[],items:(props.initial?.source_pre_order_id?props.initial.items||[]:[]).map(normalizeItem)});
const activeItemKey=ref(form.items[0]?.key||'');
watch(()=>form.items.map(i=>i.key),keys=>{if(!keys.includes(activeItemKey.value))activeItemKey.value=keys[0]||'';},{immediate:true});
function moveTab(index,delta){const item=form.items[(index+delta+form.items.length)%form.items.length];activeItemKey.value=item.key;nextTick(()=>document.getElementById('product-tab-'+item.key)?.focus());}
const sampleProducts=ref([]),availableDraft=ref(null);
const tagText=ref(''),fold=reactive({basic:false,products:false,other:false}),stock=ref([]),stockError=ref('库存加载中'),salespeople=ref([]),loading=ref(true),saving=ref(false),uploading=ref(false),error=ref(''),draftError=ref(''),draftMessage=ref(''),countdown=ref(60),dirty=ref(false),draftVersion=ref(0),fileInput=ref(null),productOpen=ref(false),productSearch=ref('');
const sessionToken=auth.token;let active=true,timer,autosavePromise=null,lastSnapshot='',previousOverflow='';
const filteredProducts=computed(()=>sampleProducts.value.filter(p=>`${p.name} ${p.style_no||p.sku}`.toLowerCase().includes(productSearch.value.toLowerCase())));
function itemTotals(it){let amount=0,qty=0;for(const c of it.colors)for(const s of c.sizes){const q=Number(s.qty||0);qty+=q;amount+=round(q*Number(it.split_price?(s.entry_price??it.unit_price):it.unit_price)/(it.currency==='CNY'?props.rate:1));}const goods=round(amount);return {goods,qty,tax:round(goods*Number(it.tax_rate||0)/100)};}
const totals=computed(()=>{let goods=0,tax=0,qty=0;for(const it of form.items){const t=itemTotals(it);goods=round(goods+t.goods);tax=round(tax+t.tax);qty+=t.qty;}const total=round(goods+tax+Number(form.freight||0)+Number(form.surcharge||0)-Number(form.discount||0));return {goods,tax,qty,total,balance:round(total-Number(form.deposit||0))};});

function restorePayload(payload){Object.assign(form,payload);const used=new Set();form.items=(payload.items||[]).map(it=>{const next=normalizeItem(it);if(used.has(next.key))next.key=entryId();used.add(next.key);return next;});}
function restoreDraft(){if(dirty.value&&!confirm('继续草稿将替换当前填写内容，确认继续？'))return;restorePayload(availableDraft.value);tagText.value=(availableDraft.value.tags||[]).join(', ');availableDraft.value=null;draftMessage.value='已恢复历史草稿';}
function snapshot(){return JSON.stringify({...form,tags:tagText.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)});}
watch([form,tagText],()=>{if(!loading.value){dirty.value=snapshot()!==lastSnapshot;draftMessage.value='';}},{deep:true});
watch(()=>auth.token,()=>{active=false;clearInterval(timer);emit('close');});
function adjust(k,delta){form[k]=round(Math.max(0,Number(form[k]||0)+delta));}
function customerChanged(){const c=props.customers.find(c=>c.id===form.customer_id);form.recipient_name=c?.contact||'';form.recipient_phone=c?.phone||'';form.shipping_address=c?.shipping_address||'';}
function toggleStock(){const open=form.items.every(i=>!i.stock_open);form.items.forEach(i=>i.stock_open=open);}
function removeItem(i){if(!confirm('确认删除这一款及其面辅料配置？'))return;const removed=form.items.splice(i,1)[0];if(removed.key===activeItemKey.value)activeItemKey.value=form.items[Math.min(i,form.items.length-1)]?.key||'';}
function selectedProduct(p){const code=String(p.style_no||p.sku||'').trim().toLowerCase();return form.items.find(it=>(p.id&&Number(it.sample_archive_id)===Number(p.id))||(code&&String(it.style_no||'').trim().toLowerCase()===code));}
function duplicateStyle(){const ids=new Set(),codes=new Set();for(const it of form.items){const code=String(it.style_no||'').trim().toLowerCase(),id=Number(it.sample_archive_id);if((id&&ids.has(id))||(code&&codes.has(code)))return code||it.product_name;if(id)ids.add(id);if(code)codes.add(code);}return '';}
function selectProduct(p){const selected=selectedProduct(p);if(selected){activeItemKey.value=selected.key;productOpen.value=false;return;}const price=p.usd_price??round(Number(p.price||0)/props.rate);const sizes=(p.sizes||[]).map(s=>typeof s==='string'?s:s.size||s.name).filter(Boolean);const colors=(p.colors||[]).map(c=>({color:typeof c==='string'?c:c.name||c.color,sizes:(sizes.length?sizes:DEFAULT_SIZES).map(size=>({size,qty:0,entry_price:price}))})).filter(c=>c.color);const it=normalizeItem({sample_archive_id:p.id,sample_archive_version:p.version,product_name:p.name,style_no:p.style_no||p.sku||'',effect_image_url:p.image_url||'',unit_price:price,colors});const blank=form.items.length===1&&!form.items[0].product_name&&!form.items[0].effect_image_url&&!form.items[0].materials.length&&!totals.value.qty;if(blank)form.items.splice(0,1,it);else form.items.push(it);activeItemKey.value=it.key;productOpen.value=false;}
async function syncMaterials(){if(!form.items.length)return;try{const catalogs=await api.materials({});let count=0;const updates=[];for(const it of form.items){if(!it.product_id&&!it.sample_archive_id)continue;const refs=await (it.sample_archive_id?api.orderSampleMaterials(it.sample_archive_id):api.orderProductMaterials(it.product_id));for(const ref of refs){const id=Number(ref.material_id||ref.id||ref),a=catalogs.find(x=>x.id===id&&x.status==='active');if(a&&!it.materials.some(m=>m.material_id===a.id)){updates.push({it,a,ref});count++;}}}for(const {it,a,ref}of updates)it.materials.push({key:entryId(),material_id:a.id,archive_version:a.version,type:a.type,role:'辅料',name:a.name,order_name:a.name,unit:a.unit||'',order_image_url:'',width:a.width||'',weight:a.weight||'',spec:a.spec||'',supplier:a.supplier||'',ingredient:a.composition||'',one_use:Number(ref.one_use||0),loss:Number(ref.loss||0),price:Number(ref.price||0),air_gap:Number(String(a.air_gap||100).replace('%','')),colors:[],usage_part:ref.usage_part||'',remark:''});alert(count?`已同步 ${count} 条辅料，请核对本单用量`:'所选商品未关联可同步的辅料，或已全部添加；可从物料档案选择。');}catch(e){error.value=e.message;}}
async function persist(){if(!active||auth.token!==sessionToken||loading.value||draftError.value)return;if(autosavePromise)return autosavePromise;const payload=JSON.parse(snapshot()),sent=JSON.stringify(payload);if(sent===lastSnapshot)return;draftMessage.value='正在保存草稿…';autosavePromise=api.saveOrderEntryDraft({scope_key:form.scope_key,version:draftVersion.value,payload}).then(r=>{if(!active)return;draftVersion.value=r.version;lastSnapshot=sent;dirty.value=snapshot()!==sent;draftMessage.value='草稿已保存';}).catch(e=>{if(active){draftError.value=e.status===409?e.message:'';draftMessage.value='草稿保存失败，请检查连接';throw e;}}).finally(()=>{autosavePromise=null;countdown.value=60;});return autosavePromise;}
async function close(){if(saving.value||uploading.value)return;try{if(dirty.value)await persist();emit('close');}catch(e){error.value=e.message;if(confirm('草稿未保存，仍要关闭？'))emit('close');}}
async function uploadFiles(files){if(uploading.value)return;uploading.value=true;try{for(const file of files){if(file.size>10*1024*1024)throw new Error('单个附件不能超过10MB');if(form.attachments.length>=30)throw new Error('最多上传30个附件');const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const a=await api.uploadFile(dataUrl,file.name);if(active)form.attachments.push(a);}}catch(e){error.value=e.message;}finally{uploading.value=false;if(fileInput.value)fileInput.value.value='';}}
async function submit(){const duplicate=duplicateStyle();if(duplicate){error.value='同一款号只能选择一次：'+duplicate;return;}error.value='';if(!form.items.length){error.value='请先选择已完成打版的样衣商品';return;}if(!form.customer_id||!form.order_no?.trim()||!form.shop_name?.trim()||!form.shop_order_no?.trim()||!tagText.value.trim()){error.value='请填写客户、销售单号、店铺名称、店铺订单编号和标签';return;}if(totals.value.total<0||totals.value.balance<0){error.value='优惠或定金超过应付金额';return;}for(const it of form.items){if(!it.product_name?.trim()){error.value='请填写每款商品名称';return;}if(!it.colors.some(c=>c.sizes.some(s=>Number(s.qty)>0))){error.value='每款至少填写一个正整数数量';return;}if(it.colors.some(c=>c.sizes.some(s=>!Number.isSafeInteger(Number(s.qty||0))||Number(s.qty)<0))){error.value='数量必须为非负整数';return;}}
  saving.value=true;try{if(autosavePromise)await autosavePromise;await persist();const body=JSON.parse(snapshot());body.draft_version=draftVersion.value;body.entry_exchange_rate=props.rate;body.items=body.items.map(it=>({...it,colors:it.colors.map(c=>({color:c.color,sizes:c.sizes.filter(s=>Number(s.qty)>0).map(s=>({size:s.size,qty:Number(s.qty),entry_price:Number(it.split_price?(s.entry_price??it.unit_price):it.unit_price),usd_price:Number(it.split_price?(s.entry_price??it.unit_price):it.unit_price)/(it.currency==='CNY'?props.rate:1)}))})).filter(c=>c.sizes.length),materials:it.materials.map(m=>({...m,colors:m.colors.filter(c=>it.colors.find(x=>x.color===c.colorway)?.sizes.some(s=>Number(s.qty)>0)).map(c=>({...c,sizes:(c.sizes||[]).filter(s=>it.colors.find(x=>x.color===c.colorway)?.sizes.some(x=>x.size===s.size&&Number(x.qty)>0))}))}))}));const created=await api.createSalesOrder(body);if(active){dirty.value=false;emit('saved',created);}}catch(e){error.value=e.message;}finally{saving.value=false;}}
onMounted(async()=>{previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';try{const r=await api.orderEntryDraft(form.scope_key);if(!active)return;draftVersion.value=r.version;if(r.payload&&form.source_pre_order_id&&r.payload.source_pre_order_version!==props.initial.source_pre_order_version){draftMessage.value='预下单已更新，已带入最新资料，请核对后保存';}else if(r.payload&&form.source_pre_order_id){restorePayload(r.payload);tagText.value=(r.payload.tags||[]).join(', ');draftMessage.value='已恢复预下单草稿';}else if(r.payload){availableDraft.value=r.payload;draftMessage.value='新单为空白，另有历史草稿可继续';}lastSnapshot=snapshot();}catch(e){draftError.value='无法读取草稿：'+e.message;}finally{loading.value=false;}
  const refs=await Promise.allSettled([api.stock({}),api.orderSalespeople(),api.orderSamples()]);if(!active)return;if(refs[0].status==='fulfilled'){stock.value=refs[0].value;stockError.value='';}else stockError.value='无库存查询权限或库存读取失败';if(refs[1].status==='fulfilled')salespeople.value=refs[1].value;if(refs[2].status==='fulfilled')sampleProducts.value=refs[2].value;else error.value='已打版样衣读取失败：'+refs[2].reason.message;
  timer=setInterval(()=>{if(!active||saving.value)return;if(countdown.value>1)countdown.value--;else{countdown.value=60;if(dirty.value)persist().catch(()=>{});}},1000);
});
onBeforeUnmount(()=>{active=false;clearInterval(timer);document.body.style.overflow=previousOverflow;});
</script>
<style src="../assets/sales-order-entry.css"></style>
